using System.Collections.Immutable;

using System.Text.Json.Serialization;

using buddy.Common.Aggregates;
using buddy.Features.Users;

namespace buddy.Features.FlashCards;

// A card set in the guardians' library. A Math set holds only its MathRule (cards are generated by
// MathDeck); a Text set holds the guardian-typed Cards. Deleting is soft: the set drops out of the
// playable lists but stays readable, so history and already earned stars keep their context.
public sealed record FlashCardSet(
    FlashCardSetId Id,
    UserId OwnerId,
    string Name,
    FlashCardSetKind Kind,
    MathRule? Math,
    ImmutableList<FlashCard> Cards,
    bool IsDeleted,
    DateTimeOffset? DeletedAt)
{
    // Snapshots deserialised without Cards would pass null; read that as empty.
    public ImmutableList<FlashCard> Cards { get; init; } = Cards ?? [];

    // How many different cards a game can draw from. A set with none cannot be enabled or played.
    public int UniqueCardCount => BuiltIn?.UniqueCardCount ?? (Math is { } rule ? MathDeck.UniqueCount(rule) : Cards.Count);

    // Set only on a synthesised built-in set (IBuiltInCatalogue). Never serialised, so stored
    // guardian snapshots keep their shape.
    [JsonIgnore]
    public BuiltInSetRef? BuiltIn { get; init; }

    public static FlashCardSet? Rehydrate(IEnumerable<FlashCardSetEvent> events) => EventReplay.Rehydrate(events, Start, Advance);

    public static FlashCardSet Replay(IEnumerable<FlashCardSetEvent> events) => EventReplay.Replay(events, Start, Advance);

    // Not named Apply/Create/Evolve: JasperFx's projection generator scans those names on any
    // projection document type (see claude-backend, section 4).
    public static FlashCardSet Start(FlashCardSetEvent @event) => @event switch
    {
        FlashCardSetCreated created => new FlashCardSet(
            created.Id,
            created.OwnerId,
            created.Name,
            created.Kind,
            created.Math,
            [],
            false,
            null),
        _ => throw EventReplay.NotAStartEvent(nameof(FlashCardSet), @event.EventType)
    };

    public static FlashCardSet Advance(FlashCardSet set, FlashCardSetEvent @event) => @event switch
    {
        FlashCardSetUpdated updated => set with { Name = updated.Name, Math = updated.Math ?? set.Math },
        FlashCardAdded added => set with { Cards = set.Cards.Add(added.Card) },
        FlashCardUpdated updated => set with
        {
            Cards = set.Cards.SetItem(IndexOf(set, updated.CardId), new FlashCard(updated.CardId, updated.Question, updated.Answer))
        },
        FlashCardRemoved removed => set with { Cards = set.Cards.RemoveAt(IndexOf(set, removed.CardId)) },
        FlashCardSetDeleted deleted => set with { IsDeleted = true, DeletedAt = deleted.OccurredAt },
        FlashCardSetCreated => throw EventReplay.AlreadyStarted(nameof(FlashCardSet), @event.EventType)
    };

    public FlashCard? FindCard(FlashCardId cardId) => Cards.FirstOrDefault(c => c.Id == cardId);

    private static int IndexOf(FlashCardSet set, FlashCardId cardId)
    {
        var index = set.Cards.FindIndex(c => c.Id == cardId);

        return index >= 0
            ? index
            : throw new InvalidOperationException($"Flash card {cardId.Value} is not on set {set.Id.Value}.");
    }
}
